public class ZipArchiveInputStream_read_TriageGen0Test {

    @Test(expected = IOException.class)
    public void testRead_WhenClosed() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("test.txt");
            zos.putNextEntry(entry);
            zos.write("data".getBytes());
            zos.closeEntry();
        }

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();
        zais.close();

        byte[] buffer = new byte[10];
        zais.read(buffer, 0, 10);
    }

    @Test
    public void testRead_WhenFinishedOrNullCurrent() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            zos.putNextEntry(new ZipEntry("test.txt"));
            zos.write("data".getBytes());
            zos.closeEntry();
        }

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        // No getNextEntry called, current is null
        int result = zais.read(new byte[10], 0, 10);
        Assert.assertEquals(-1, result);

        zais.getNextZipEntry();
        zais.close();
        // After close/finished
        int resultFinished = zais.read(new byte[10], 0, 10);
        Assert.assertEquals(-1, resultFinished);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_InvalidBufferBounds() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            zos.putNextEntry(new ZipEntry("test.txt"));
            zos.write("data".getBytes());
            zos.closeEntry();
        }
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        // start > buffer.length
        zais.read(new byte[5], 6, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeStart() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            zos.putNextEntry(new ZipEntry("test.txt"));
            zos.write("data".getBytes());
            zos.closeEntry();
        }
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        zais.read(new byte[5], -1, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeLength() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            zos.putNextEntry(new ZipEntry("test.txt"));
            zos.write("data".getBytes());
            zos.closeEntry();
        }
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        zais.read(new byte[5], 0, -1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_LengthOverflowsBuffer() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            zos.putNextEntry(new ZipEntry("test.txt"));
            zos.write("data".getBytes());
            zos.closeEntry();
        }
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        // buffer.length - start < length
        zais.read(new byte[5], 2, 4);
    }

    @Test
    public void testRead_DeflatedData() throws IOException {
        String content = "This is a test string for deflation";
        byte[] contentBytes = content.getBytes();

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("test.txt");
            zos.putNextEntry(entry);
            zos.write(contentBytes);
            zos.closeEntry();
        }

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        int read = zais.read(buffer, 0, 10);
        Assert.assertEquals(10, read);
        Assert.assertArrayEquals(new byte[]{contentBytes[0], contentBytes[1], contentBytes[2], contentBytes[3], contentBytes[4], contentBytes[5], contentBytes[6], contentBytes[7], contentBytes[8], contentBytes[9]}, buffer, 0, 10);

        zais.close();
    }

